import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        boolean[] composite = new boolean[Math.max(n, 2)];
        for (int p = 2; p < n; p++)
            if (!composite[p])
                for (long m = (long) p * p; m < n; m += p) composite[(int) m] = true;
        List<Integer> steps = new ArrayList<>();
        steps.add(1);
        for (int p = 3; p < n; p += 10) if (!composite[p]) steps.add(p); // primes ending in 3
        long[] dp = new long[n];
        for (int i = 1; i < n; i++) {
            long best = Long.MIN_VALUE;
            for (int s : steps) if (s <= i) best = Math.max(best, dp[i - s]);
            dp[i] = a[i] + best;
        }
        System.out.println(dp[n - 1]);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	composite := make([]bool, max(n, 2))
	for p := 2; p < n; p++ {
		if !composite[p] {
			for m := p * p; m < n; m += p {
				composite[m] = true
			}
		}
	}
	steps := []int{1}
	for p := 3; p < n; p += 10 { // primes ending in 3
		if !composite[p] {
			steps = append(steps, p)
		}
	}
	dp := make([]int, n)
	for i := 1; i < n; i++ {
		best := math.MinInt64
		for _, s := range steps {
			if s <= i {
				best = max(best, dp[i-s])
			}
		}
		dp[i] = a[i] + best
	}
	fmt.Println(dp[n-1])
}
